fields.InputDefinition:
{
  "goal": "Open the 'Events' entity via the LEFT sidebar 'Search entities...' box, click an event row, then 'Open Full Record'. Click Edit to enter edit mode — an edit banner appears at the top. Modify one editable text field (e.g. Location or Description) to a new value. Confirm the banner updates to show a count of modified fields (e.g. '1 field modified') and lists the changed field name(s). Success is the banner reflecting the dirty-field count/name after your edit — you do NOT need to save. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Entering edit mode shows an edit banner with Save/Discard actions",
    "After editing a field, the banner reports the number of modified fields and/or names the changed field",
    "No error messages, blank screens, or crash pages"
  ]
}
